final class TrieTest {
    private TrieTest() {
    }

    public static void main(String[] args) {
        testInsertAndSearch();
        testPrefixChecks();
        testMissingAndInvalidInputs();
        System.out.println("All Trie tests passed.");
    }

    private static void testInsertAndSearch() {
        Trie trie = new Trie();
        trie.insert("and");
        trie.insert("ant");
        trie.insert("do");

        expectTrue(trie.search("and"), "Expected 'and' to be found");
        expectTrue(trie.search("ant"), "Expected 'ant' to be found");
        expectTrue(trie.search("do"), "Expected 'do' to be found");
        expectFalse(trie.search("an"), "Expected 'an' not to be found");
        expectFalse(trie.search("dog"), "Expected 'dog' not to be found");
    }

    private static void testPrefixChecks() {
        Trie trie = new Trie();
        trie.insert("dad");
        trie.insert("dart");

        expectTrue(trie.startsWith("da"), "Expected 'da' to be a prefix");
        expectTrue(trie.isPrefix("dar"), "Expected 'dar' to be a prefix");
        expectFalse(trie.startsWith("de"), "Expected 'de' not to be a prefix");
        expectFalse(trie.isPrefix("dads"), "Expected 'dads' not to be a prefix");
    }

    private static void testMissingAndInvalidInputs() {
        Trie trie = new Trie();

        expectFalse(trie.search("missing"), "Expected missing word to return false");
        expectFalse(trie.startsWith("missing"), "Expected missing prefix to return false");

        expectThrows(
            IllegalArgumentException.class,
            () -> trie.insert("Do"),
            "Expected uppercase input to be rejected");
        expectThrows(
            IllegalArgumentException.class,
            () -> trie.search(null),
            "Expected null input to be rejected");
        expectThrows(
            IllegalArgumentException.class,
            () -> trie.startsWith("do-"),
            "Expected punctuation to be rejected");
    }

    private static void expectTrue(boolean value, String message) {
        if (!value) {
            throw new AssertionError(message);
        }
    }

    private static void expectFalse(boolean value, String message) {
        if (value) {
            throw new AssertionError(message);
        }
    }

    private static void expectThrows(
        Class<? extends Throwable> expectedType,
        CheckedRunnable action,
        String message) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (expectedType.isInstance(thrown)) {
                return;
            }
            throw new AssertionError(
                message + " but got " + thrown.getClass().getSimpleName(),
                thrown);
        }

        throw new AssertionError(message);
    }

    @FunctionalInterface
    private interface CheckedRunnable {
        void run();
    }
}

public class Trie {
    private static final int ALPHABET_SIZE = 26;
    private static final String LOWERCASE_ONLY_MESSAGE =
        "Trie only supports lowercase letters a-z: '";

    private final TrieNode root = new TrieNode();

    public void insert(String word) {
        TrieNode node = walk(word, true);
        node.isWord = true;
    }

    public boolean search(String word) {
        TrieNode node = walk(word, false);
        return node != null && node.isWord;
    }

    public boolean isPrefix(String prefix) {
        return startsWith(prefix);
    }

    public boolean startsWith(String prefix) {
        return walk(prefix, false) != null;
    }

    private TrieNode walk(String text, boolean createMissing) {
        if (text == null) {
            throw new IllegalArgumentException("Text cannot be null");
        }
        validateText(text);

        TrieNode node = root;
        for (int i = 0; i < text.length(); i++) {
            int index = toIndex(text.charAt(i));
            TrieNode next = node.children[index];
            if (next == null) {
                if (!createMissing) {
                    return null;
                }
                next = new TrieNode();
                node.children[index] = next;
            }
            node = next;
        }
        return node;
    }

    private static void validateText(String text) {
        for (int i = 0; i < text.length(); i++) {
            toIndex(text.charAt(i));
        }
    }

    private static int toIndex(char c) {
        if (c < 'a' || c > 'z') {
            throw new IllegalArgumentException(LOWERCASE_ONLY_MESSAGE + c + "'");
        }
        return c - 'a';
    }

    private static final class TrieNode {
        private final TrieNode[] children = new TrieNode[ALPHABET_SIZE];
        private boolean isWord;
    }
}
